INSERT INTO VERTICALIZZAZIONIBASE (MODULO, DESCRIZIONE) VALUES ('PROTOCOLLO_EPROT', 'Verticalizzazione che serve per gestire il protocollo E-PROT, attualmente in uso all''Arpa Umbria, i servizi sono di tipo rest ed usa autenticazione basic.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_EPROT', 'URL_BASE', 'Parametro che sta ad indicare la url base di dove possono essere invocati i metodi del web service, da notare che il web service è di tipo rest e che viene utilizzata un''autenticazione di tipo basic, questo sta a significare che i metodi vengono inseriti direttamente sulla stringa relativa alla url, ad esempio, se si vuole invocare il metodo di lettura delle tipologie di documento va aggiunto, alla url, "/richiesta_tipi_documento", per il titolario "/richiesta_titolario", per le protocollazioni in entrata e uscita "/richiesta_protocollazione_ingresso" e "/richiesta_protocollazione_uscita, questo comunque viene fatto direttamente dal sistema e non va indicato in questo parametro, dove invece va inserita solamente la url base"');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_EPROT', 'USERNAME', 'Indicare la username per autenticarsi al web service che utilizza un tipo di autenticazione basic, le credenziali sono riferite agli utenti del protocollo.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_EPROT', 'PASSWORD', 'Indicare la password per autenticarsi al web service che utilizza un tipo di autenticazione basic, le credenziali sono riferite agli utenti del protocollo.');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIELMERCATO', 'REGISTRO', 'Indicare il registro relativo al protocollo, da questo parametro sarà possibile anche recuperare il parametro officecode che dovrà essere implementato sulla tabella PROTOCOLLO_UFFICIREGISTRI');
INSERT INTO VERTICALIZZAZIONIPARAMETRIBASE (MODULO, PARAMETRO, DESCRIZIONE) VALUES ('PROTOCOLLO_INSIELMERCATO', 'CODICE_UFFICIO_OPERANTE', 'Indica il codice ufficio su cui un utente può operare, di norma va di pari passo con il software (SUAP, EDILIZIA, COMMERCIO....)');
INSERT INTO verticalizzazionibase (modulo, descrizione, flag_gestcomune) VALUES ('PAGAMENTI_LIVORNO', 'Modulo per la gestione dei pagamenti del comune di Livorno',0);
INSERT INTO verticalizzazioniparametribase (modulo, parametro, descrizione) VALUES ('PAGAMENTI_LIVORNO', 'WS_URL', 'Url del web service per la validazione dei codici digitali di pagamento (es.http://wscitel.comune.livorno.it:8080/axis2/services/ws_dia/) ');
INSERT INTO verticalizzazioniparametribase (modulo, parametro, descrizione) VALUES ('PAGAMENTI_LIVORNO', 'ID_CAMPO_DINAMICO', 'Id del campo dinamico in cui viene memorizzato il codice pagamento. Utilizzato per verificare che il codice non sia già stato usato');
